# Selective deletion: create two comments, delete one, verify the other remains
POST {{host}}/api/articles/{{slug}}/comments
Authorization: Token {{token}}
{
  "comment": {
    "body": "First comment"
  }
}
HTTP 201
[Captures]
first_comment_id: jsonpath "$.comment.id"

POST {{host}}/api/articles/{{slug}}/comments
Authorization: Token {{token}}
{
  "comment": {
    "body": "Second comment"
  }
}
HTTP 201

# Verify two comments exist
GET {{host}}/api/articles/{{slug}}/comments
HTTP 200
[Asserts]
jsonpath "$.comments" count == 2

# Delete the first comment
DELETE {{host}}/api/articles/{{slug}}/comments/{{first_comment_id}}
Authorization: Token {{token}}
HTTP 204

# Verify only the second comment remains
GET {{host}}/api/articles/{{slug}}/comments
HTTP 200
[Asserts]
jsonpath "$.comments" count == 1
jsonpath "$.comments[0].body" == "Second comment"

test('should delete own comment', async ({ page }) => {
  const commentText = 'Comment to be deleted';
  await addComment(page, commentText);
  // Comment should be visible
  await expect(page.locator(`.card:not(.comment-form) .card-block:has-text("${commentText}")`)).toBeVisible();
  // Delete the comment
  await deleteComment(page, commentText);
  // Comment should no longer be visible
  await expect(page.locator(`.card:not(.comment-form) .card-block:has-text("${commentText}")`)).not.toBeVisible();
});
